def yuklenici_df():
    import pandas as pd
    d = pd.DataFrame(YUKLENICI)
    d["plan"] = 0.0
    d["gercek"] = 0.0
    return d


def progress_rows():
    """Yüklenici hakediş kalemlerini ana çalışma şemasına (progress) çevirir.
    grup → hem grp (kapsam/grup) hem disc (disiplin) olarak kullanılır."""
    rows = []
    for it in YUKLENICI:
        rows.append({
            "id": it["poz"], "grp": it["grup"], "disc": it["grup"],
            "name": it["ad"], "unit": it["birim"],
            "qty": float(it["miktar"]), "up": float(it["bf"]),
            "plan": 0.0, "real": 0.0,
        })
    return rows
